function disconnectedLabel(s,instance){const status=String(instance?.status??'');if(status==='2')return '云端已关机 · 点击生成时自动启动';if(status==='6')return '云端实例已销毁 · 请重新选择';if(status==='4')return '云端正在关机';if(status==='3'||status==='8')return '云端正在启动 · 等待连接';if(status==='0')return '云端正在部署 · 等待启动';if(resourceConnection===false){if(status==='1')return '云端已开机 · ComfyUI未连接';return s.applicationId?'云端未连接 · 正在确认服务器状态':'云端未启动 · 点击生成时自动启动';}return '';}
