if(location.pathname==='/tools.html'){const originalFetch=window.fetch.bind(window);window.fetch=async function(url,options){const route=String(url);if(route==='/api/tools/jobs'&&options?.method==='POST'){let payload;try{payload=JSON.parse(options.body)}catch{}if(payload&&['text-video','image-video'].includes(payload.kind)&&Number(payload.port)===18191){const response=await originalFetch('/api/lightcc/selection',{cache:'no-store'}),s=(await response.json()).selection;if(!s){alert('\u4e91\u6ca1\u9009\uff0c\u8bf7\u5148\u9009\u62e9GPU');location.href='/lightcc.html';throw Error('No cloud configuration selected')}options={...options,body:JSON.stringify({...payload,cloudSelectionId:s.id})}}}return originalFetch(url,options)}}
