async function refreshResources(){if(resourceBusy||bar.hidden||document.hidden)return;resourceBusy=true;try{const response=await fetch('/api/lightcc/status',{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error();const {connection:c}=await response.json();resourceConnection=!!c?.online;if(!c?.online){resources.textContent='显存 / 内存：云端未连接';return;}const format=(total,free)=>{if(!Number.isFinite(total)||!Number.isFinite(free)||total<=0)return '暂不可用';const used=Math.max(0,Math.min(total,total-free));return (used/1073741824).toFixed(1)+' / '+(total/1073741824).toFixed(1)+' GB';};resources.textContent='显存：'+format(c.vramTotalBytes,c.vramFreeBytes)+'\n内存：'+format(c.ramTotalBytes,c.ramFreeBytes);resources.title='云端整机已用 / 总量，每10秒刷新';}catch{resources.textContent='显存 / 内存：暂不可用';}finally{resourceBusy=false;}}
